style.css:
@-moz-document domain("checkvist.com") {
/* Palette (change colors here) */
:root {
  --dv-bg:          #232221;   /* page background */
  --dv-bg-2:        #2b2a28;   /* toolbars, panels */
  --dv-bg-3:        #343330;   /* inputs, notes */
  --dv-border:      #45433f;
  --dv-text:        #bdb9b2;   /* base text, dimmed warm grey */
  --dv-text-dim:    #7d7a75;   /* completed items, footer */
  --dv-strong:      #e6e2db;   /* bold text, title */
  --dv-accent:      #c98a4b;   /* muted orange */
  --dv-accent-soft: rgba(201, 138, 75, 0.12);
  --dv-accent-dim:  #6b4a2b;   /* tag background */
  --dv-link:        #d2a06b;   /* soft amber */
  --dv-select:      rgba(255, 255, 255, 0.08);  /* cursor row, pale grey */
  --dv-select-line: #6a6864;   /* cursor row border */
}

/* Base page and text color */
html, body, .main_div, .cl_content, #ffContainer {
  background: var(--dv-bg) !important;
  color: var(--dv-text) !important;
}

/* --------------------------------------------------------------------------
   Top bar and toolbar
   -------------------------------------------------------------------------- */
.topbarDiv, .toolbarDiv, .toolBar {
  background: var(--dv-bg-2) !important;
  color: var(--dv-text) !important;
  border-color: var(--dv-border) !important;
  text-shadow: none !important;
}
a.topbar__navLink, a.topbar__navLink:visited,
.toolBar a, .toolBar a#viewOptionsLink, .toolBar .expandCollapse {
  color: var(--dv-text) !important;
}

/* Logo - light rounded badge so it stays readable on dark */
img.logoImg {
  background: #e6e2db !important;
  padding: 5px !important;
  margin: -5px !important;
  border-radius: 12px !important;
}

/* --------------------------------------------------------------------------
   List title and task text
   -------------------------------------------------------------------------- */
.list-h1 {
  color: var(--dv-strong) !important;
  text-shadow: none !important;
}
.userContent, .taskContent {
  color: var(--dv-text) !important;
}

/* Bold formatting - brighter */
.userContent strong, .userContent b {
  color: var(--dv-strong) !important;
}

/* Italic text - dimmed */
.taskContent em, .userContent em {
  opacity: 0.75 !important;
}

/* Inline links - soft amber */
.userContent a, .userContent a:visited {
  color: var(--dv-link) !important;
}

/* Inline code - dark background, sand text */
.userContent code {
  background: rgba(0, 0, 0, 0.25) !important;
  color: #b89468 !important;
  border-color: var(--dv-border) !important;
}

/* --------------------------------------------------------------------------
   Task states
   -------------------------------------------------------------------------- */

/* Selected / focused task (cursor) - pale grey */
div.coreDiv.selectedTask,
.selectedTask_focus > div.coreDiv,
ul.comments li.comment.selectedTask div.coreNote,
li.comment.selectedTask_focus div.coreNote,
li.upload.selectedTask_focus {
  background: var(--dv-select) !important;
  border-color: var(--dv-select-line) !important;
}

/* Completed tasks - grey, stroked through */
span.task_closed,
.userContent.task_closed,
.userContent.task_closed strong,
.userContent.task_closed a {
  color: var(--dv-text-dim) !important;
}

/* The inline wrapper around a selected task's text also carries its own
   background (independent of .coreDiv) - without this it stays light and
   shows as a mismatched box behind the text. */
.selectedTask .priorityColored,
.selectedTask_focus .priorityColored {
  background: transparent !important;
}

/* Vertical guide lines - faint */
.verticalGuide, .verticalGuide__selected {
  opacity: 0.25 !important;
}

/* --------------------------------------------------------------------------
   Task colors (Checkvist's built-in color/priority marks)
   -------------------------------------------------------------------------- */

/* Foreground colors: 1 = red, 2 = green, 3 = blue (muted for dark) */
.color_fg1, span.fg1 .userContent, span.fg1 .userContent a { color: #d9877a !important; }
.color_fg2, span.fg2 .userContent, span.fg2 .userContent a { color: #8fb593 !important; }
.color_fg3, span.fg3 .userContent, span.fg3 .userContent a { color: #8aa8cf !important; }

/* Bold text keeps the color of its mark */
span.fg1 .userContent strong, span.fg2 .userContent strong, span.fg3 .userContent strong {
  color: inherit !important;
}

/* Background marks: 1 = red, 2 = green, 3 = blue (deep tones, light text) */
span.bg1, span.bg1 .userContent, span.bg1 .userContent a { color: #f0d6d0 !important; }
span.bg2, span.bg2 .userContent, span.bg2 .userContent a { color: #d5e6d8 !important; }
span.bg3, span.bg3 .userContent, span.bg3 .userContent a { color: #d6def0 !important; }
span.bg1 { background: #5a3a35 !important; }
span.bg2 { background: #34473a !important; }
span.bg3 { background: #363f52 !important; }

/* --------------------------------------------------------------------------
   Notes / comments
   -------------------------------------------------------------------------- */
ul.comments {
  background: var(--dv-bg-3) !important;
}
li.comment, li.comment:first-of-type {
  border-color: var(--dv-border) !important;
}

/* --------------------------------------------------------------------------
   Tags and due dates
   -------------------------------------------------------------------------- */
.tagClass_0, a.tagClass_0 {
  background-color: var(--dv-accent-dim) !important;
  border-color: var(--dv-accent-dim) !important;
  color: #f0e2d0 !important;
}
li.task div.coreDiv span.dueDate {
  border-color: var(--dv-border) !important;
  color: #a5a19a !important;
}
li.task div.coreDiv span.dueDate.overdue {
  border-color: #a5533a !important;
  color: #f0d8ce !important;
}

/* --------------------------------------------------------------------------
   Inputs and buttons
   -------------------------------------------------------------------------- */
.text_input, #task_content, textarea,
input[type="text"], input[type="search"] {
  background: var(--dv-bg-3) !important;
  border-color: var(--dv-border) !important;
  color: var(--dv-strong) !important;
}
.singleLineForm button.submit, .singleLineForm a.editor_cancel {
  background: var(--dv-bg-3) !important;
  border-color: var(--dv-border) !important;
  color: var(--dv-text) !important;
}

/* Autocomplete suggestions keep dark text on their light box */
.suggestionBox {
  color: #222 !important;
}

/* --------------------------------------------------------------------------
   Divider ("----")
   -------------------------------------------------------------------------- */
div.hrDivider {
  background: rgba(255, 255, 255, 0.15) !important;
}

/* --------------------------------------------------------------------------
   Side navigation, popups and shortcuts panel
   -------------------------------------------------------------------------- */
.leftColumnNav, .kbdShortcuts, .kbdShortcuts td {
  background: var(--dv-bg-2) !important;
  color: var(--dv-text) !important;
  text-shadow: none !important;
}
.leftColumnNav ul li, .kbdShortcuts td {
  border-color: var(--dv-border) !important;
}
.additionalText, ul.checklists li.list_item,
#archivedListSection .checklistName a, .progressCounterText,
.menuPopupList li a, .menuPopupList li a:visited {
  color: var(--dv-text) !important;
}
.menuPopupList, .popupDiv, .dialog {
  background: var(--dv-bg-2) !important;
  border-color: var(--dv-border) !important;
  color: var(--dv-text) !important;
}

/* --------------------------------------------------------------------------
   Text selection and focus outline
   The grey box with a dark border behind selected/focused task text is the
   browser's default text-selection and focus-ring styling, unstyled by
   Checkvist itself - both are overridden here.
   -------------------------------------------------------------------------- */
::selection {
  background: var(--dv-select-line) !important;
  color: var(--dv-strong) !important;
}
*:focus, [contenteditable]:focus, .taskContent:focus {
  outline-color: var(--dv-select-line) !important;
}

/* --------------------------------------------------------------------------
   Lists overview page (My Lists / Active / Archived)
   Verified against the live DOM: rows are <li class="list_item"> inside
   <ul class="checklists">; the highlighted row adds list_item--selected
   (and list_item--selected_focus), which colors every .checklists__cell
   inside it - that cell background is what carries the highlight, not
   the row itself.
   -------------------------------------------------------------------------- */
.checklists {
  background: transparent !important;
}
.list_item {
  color: var(--dv-text) !important;
}
.list_item__list-name-link {
  color: var(--dv-strong) !important;
}
.list_item__last-updated,
.list_item__share-info,
.list_item__share-link,
.list_item__progress-info {
  color: var(--dv-text-dim) !important;
}
.list_item:hover .checklists__cell,
.list_item--selected .checklists__cell,
.list_item--selected_focus .checklists__cell {
  background: var(--dv-select) !important;
}

/* --------------------------------------------------------------------------
   Footer
   -------------------------------------------------------------------------- */
.pageFooter, .pageFooter__inner {
  background: var(--dv-bg) !important;
  color: var(--dv-text-dim) !important;
}
}
